-- G: replace placeholder titles with the catalog's church names (optional). Generated by generate.py.
BEGIN;
CREATE TEMP TABLE gt(full_code text, title text);
UPDATE files f SET title = gt.title FROM gt WHERE f.full_code = gt.full_code AND (f.title ~* '^(Церковні документи|Метричні книги Православних церков|Метричні книги$|Metrical Books and Clergy Records|Метричні книги,\s*Nobility|Nobility)');
-- church lines that already start with «Метричні книги …» (пароплави) must not get a second prefix
UPDATE files f SET title = regexp_replace(f.title, '^Метрична книга\. (Метричні книги )', '\1') FROM gt WHERE f.full_code = gt.full_code AND f.title ~ '^Метрична книга\. Метричні книги ';
SELECT 'titles replaced', count(*) FROM gt JOIN files f ON f.full_code = gt.full_code WHERE f.title = gt.title;
